INSERT INTO lesson (id, unit_id, knowledge_tag_id, title, description, order_index, estimated_minutes, lesson_type, skill, situation_tag, is_review, status) VALUES
(1, 1, 4, 'Bài 1: Giới thiệu bản thân — tên, nghề nghiệp, quốc gia', 'Mẫu câu, lời giải thích, bảng luyện, mẩu đổi vai và đoạn đọc do Sekai Gen tự soạn theo các cấu trúc ngữ pháp của bài. Không chép nội dung sách 3A Corporation.', 1, 45, 'CURRICULUM', 'GRAMMAR', 'FOUNDATION', 0, 'PUBLISHED'),
(2, 1, 5, 'Bài 2: Đồ vật quanh mình: cái này, cái kia, của ai', 'Vốn từ chọn theo chủ đề và trình tự ngữ pháp trình độ N5 (kiến thức chung) từ nguồn mở, cộng phần từ riêng của Sekai Gen. Mẫu câu, câu ví dụ, hội thoại, bảng luyện và bài tập do Sekai Gen tự soạn. Không chép nội dung của bất kỳ giáo trình thương mại nào.', 2, 45, 'CURRICULUM', 'GRAMMAR', 'FOUNDATION', 0, 'PUBLISHED'),
(3, 1, 6, 'Bài 3: Chỗ này chỗ kia: hỏi đường và hỏi giá', 'Vốn từ chọn theo chủ đề và trình tự ngữ pháp trình độ N5 (kiến thức chung) từ nguồn mở, cộng phần từ riêng của Sekai Gen. Mẫu câu, câu ví dụ, hội thoại, bảng luyện và bài tập do Sekai Gen tự soạn. Không chép nội dung của bất kỳ giáo trình thương mại nào.', 3, 45, 'CURRICULUM', 'GRAMMAR', 'FOUNDATION', 0, 'PUBLISHED'),
(4, 1, 7, 'Bài 4: Mấy giờ làm gì: giờ giấc và việc trong ngày', 'Vốn từ chọn theo chủ đề và trình tự ngữ pháp trình độ N5 (kiến thức chung) từ nguồn mở, cộng phần từ riêng của Sekai Gen. Mẫu câu, câu ví dụ, hội thoại, bảng luyện và bài tập do Sekai Gen tự soạn. Không chép nội dung của bất kỳ giáo trình thương mại nào.', 4, 45, 'CURRICULUM', 'GRAMMAR', 'FOUNDATION', 0, 'PUBLISHED'),
