INSERT INTO content_item (id, section_id, content_type, grammar_point_id, title, content, translated_text, order_index) VALUES
(1, 1, 'READING', NULL, 'Danh sách từ vựng bài 1', 'Bài 1 có 54 từ vựng.', NULL, 1),
(2, 3, 'GRAMMAR', 1, 'Ví dụ 1', 'わたしは グエンです。', 'Tôi là Nguyễn.', 1),
(3, 3, 'GRAMMAR', 3, 'Ví dụ 2', 'ちちは かいしゃいんです。', 'Bố tôi là nhân viên công ty.', 2),
(4, 3, 'GRAMMAR', 6, 'Ví dụ 3', 'あねは ぎんこういんです。', 'Chị tôi là nhân viên ngân hàng.', 3),
(5, 3, 'GRAMMAR', 6, 'Ví dụ 4', 'おなまえは。', 'Bạn tên là gì?', 4),
(6, 3, 'GRAMMAR', 5, 'Ví dụ 5', 'わたしは ベトナムじんです。', 'Tôi là người Việt Nam.', 5),
(7, 3, 'GRAMMAR', 1, 'Ví dụ 6', 'はじめまして。グエンです。', 'Rất vui được gặp. Tôi là Nguyễn.', 6),
(8, 3, 'GRAMMAR', 1, 'Ví dụ 7', 'しつれいですが、おなまえは。', 'Xin lỗi cho hỏi, bạn tên là gì?', 7),
(9, 3, 'GRAMMAR', 3, 'Ví dụ 8', 'はい、そうです。', 'Vâng, đúng vậy.', 8),
(10, 3, 'GRAMMAR', 5, 'Ví dụ 9', 'いいえ、ちがいます。がくせいです。', 'Không, không phải. Tôi là sinh viên.', 9),
(11, 3, 'GRAMMAR', 5, 'Ví dụ 10', 'はい、わたしは かいしゃいんです。', 'Vâng, tôi là nhân viên công ty.', 10),
(12, 3, 'GRAMMAR', 5, 'Ví dụ 11', 'おとうとは こうむいんです。', 'Em trai tôi là công chức nhà nước.', 11),
(13, 3, 'GRAMMAR', 5, 'Ví dụ 12', 'ははは しゅふです。', 'Mẹ tôi là người nội trợ.', 12),
(14, 3, 'GRAMMAR', NULL, 'Ví dụ 13', 'しゅっしんは ハノイです。', 'Quê tôi ở Hà Nội.', 13),
(15, 3, 'GRAMMAR', 3, 'Ví dụ 14', 'しゅみは りょうりです。', 'Sở thích của tôi là nấu ăn.', 14),
(16, 3, 'GRAMMAR', 6, 'Ví dụ 15', 'かぞくは よにんです。', 'Gia đình tôi có bốn người.', 15),
(17, 3, 'GRAMMAR', 1, 'Ví dụ 16', 'せんもんは にほんごです。', 'Chuyên ngành của tôi là tiếng Nhật.', 16),
(18, 3, 'GRAMMAR', 6, 'Ví dụ 17', 'いいえ、いしゃじゃ ありません。', 'Không, tôi không phải bác sĩ.', 17),
(19, 3, 'GRAMMAR', 4, 'Ví dụ 18', 'あのひとは せんせいじゃ ありません。', 'Người kia không phải giáo viên.', 18),
(20, 3, 'GRAMMAR', 6, 'Ví dụ 19', 'たなかさんは がいこくじんじゃ ありません。', 'Anh Tanaka không phải người nước ngoài.', 19),
(21, 3, 'GRAMMAR', 6, 'Ví dụ 20', 'あなたは がくせいですか。', 'Bạn là sinh viên phải không?', 20),
(22, 3, 'GRAMMAR', 5, 'Ví dụ 21', 'リンさんは いしゃですか。', 'Chị Linh là bác sĩ phải không?', 21),
(23, 3, 'GRAMMAR', 3, 'Ví dụ 22', 'おくには どちらですか。', 'Bạn ở nước nào?', 22),
(24, 3, 'GRAMMAR', 7, 'Ví dụ 23', 'あのひとは だれですか。', 'Người kia là ai vậy?', 23),
(25, 3, 'GRAMMAR', NULL, 'Ví dụ 24', 'おしごとは なんですか。', 'Anh làm nghề gì?', 24),
(26, 3, 'GRAMMAR', 8, 'Ví dụ 25', 'キムさんも かんこくじんです。', 'Anh Kim cũng là người Hàn Quốc.', 25),
(27, 3, 'GRAMMAR', NULL, 'Ví dụ 26', 'マイクさんも えいごの せんせいです。', 'Anh Mike cũng là giáo viên tiếng Anh.', 26),
(28, 3, 'GRAMMAR', NULL, 'Ví dụ 27', 'ソムさんも タイの がくせいです。', 'Anh Som cũng là sinh viên người Thái.', 27),
(29, 3, 'GRAMMAR', NULL, 'Ví dụ 28', 'わたしは だいがくの がくせいです。', 'Tôi là sinh viên đại học.', 28),
(30, 3, 'GRAMMAR', 1, 'Ví dụ 29', 'かれは だいがくの けんきゅうしゃです。', 'Anh ấy là người làm nghiên cứu ở trường đại học.', 29),
(31, 3, 'GRAMMAR', 2, 'Ví dụ 30', 'わたしの かいしゃは とうきょうです。', 'Công ty của tôi ở Tokyo.', 30),
(32, 3, 'GRAMMAR', 5, 'Ví dụ 31', 'この だいがくは ゆうめいです。', 'Trường đại học này nổi tiếng.', 31),
(33, 3, 'GRAMMAR', 5, 'Ví dụ 32', 'はははびょういんの かんごしです。', 'Mẹ tôi là y tá ở bệnh viện.', 32),
(34, 3, 'GRAMMAR', 1, 'Ví dụ 33', 'これは にほんごの ほんです。', 'Đây là sách tiếng Nhật.', 33),
(35, 3, 'GRAMMAR', 5, 'Ví dụ 34', 'あねは びょういんの かんごしです。', 'Chị tôi là y tá ở bệnh viện.', 34),
(36, 3, 'GRAMMAR', 5, 'Ví dụ 35', 'あのひとは コンビニの てんいんです。', 'Người kia là nhân viên cửa hàng tiện lợi.', 35),
(37, 3, 'GRAMMAR', 5, 'Ví dụ 36', 'わたしは ITかいしゃの エンジニアです。', 'Tôi là kỹ sư của một công ty tin học.', 36),
(38, 3, 'GRAMMAR', 1, 'Ví dụ 37', 'ちちは バスの うんてんしゅです。', 'Bố tôi là tài xế xe buýt.', 37),
(39, 3, 'GRAMMAR', 6, 'Ví dụ 38', 'かれは にほんりょうりの りょうりにんです。', 'Anh ấy là đầu bếp món Nhật.', 38),
(40, 3, 'GRAMMAR', 5, 'Ví dụ 39', 'これは わたしの めいしです。', 'Đây là danh thiếp của tôi.', 39),
(41, 3, 'GRAMMAR', 1, 'Ví dụ 40', 'たなかさんは せんせいです。', 'Anh Tanaka là giáo viên.', 40),
(42, 3, 'GRAMMAR', 1, 'Ví dụ 41', 'やまださんは にほんごの せんせいです。', 'Chị Yamada là giáo viên tiếng Nhật.', 41),
(43, 3, 'GRAMMAR', 1, 'Ví dụ 42', 'やまださんは にほんじんです。', 'Chị Yamada là người Nhật.', 42),
(44, 3, 'GRAMMAR', 8, 'Ví dụ 43', 'マイクさんは アメリカじんです。', 'Anh Mike là người Mỹ.', 43),
(45, 3, 'GRAMMAR', 2, 'Ví dụ 44', 'ワンさんは ちゅうごくの けんきゅうしゃです。', 'Anh Vương là người làm nghiên cứu ở Trung Quốc.', 44),
(46, 3, 'GRAMMAR', 3, 'Ví dụ 45', 'たなかさんは にほんじんです。', 'Anh Tanaka là người Nhật.', 45),
(47, 3, 'GRAMMAR', 1, 'Ví dụ 46', 'たなかさんは わたしの どうりょうです。', 'Anh Tanaka là đồng nghiệp của tôi.', 46),
(48, 3, 'GRAMMAR', 7, 'Ví dụ 47', 'キムさんは わたしの ともだちです。', 'Anh Kim là bạn của tôi.', 47),
(49, 3, 'GRAMMAR', 7, 'Ví dụ 48', 'エマさんは イギリスじんです。', 'Chị Emma là người Anh.', 48),
(50, 3, 'GRAMMAR', 6, 'Ví dụ 49', 'おこさんは なんさいですか。', 'Con của anh mấy tuổi rồi?', 49),
(51, 3, 'GRAMMAR', 8, 'Ví dụ 50', 'おとうとは じゅっさいです。', 'Em trai tôi mười tuổi.', 50),
(52, 3, 'GRAMMAR', 4, 'Ví dụ 51', 'しつれいですが、おいくつですか。', 'Xin lỗi cho hỏi, anh bao nhiêu tuổi?', 51),
(53, 3, 'GRAMMAR', 6, 'Ví dụ 52', 'ベトナムから きました。どうぞ よろしく。', 'Tôi đến từ Việt Nam. Mong được giúp đỡ.', 52),
(54, 3, 'GRAMMAR', 4, 'Ví dụ 53', 'こちらは たなかさんです。どうぞ よろしく。', 'Đây là anh Tanaka. Mong được giúp đỡ.', 53),
(55, 3, 'GRAMMAR', 2, 'Ví dụ 54', 'どうも。はじめまして。どうぞ よろしく。', 'Xin chào. Rất vui được gặp. Mong được giúp đỡ.', 54),
(56, 4, 'LISTENING', NULL, 'Tanaka', 'はじめまして。たなかです。', 'Rất vui được gặp. Tôi là Tanaka.', 1),
(57, 4, 'LISTENING', NULL, 'Nguyễn', 'はじめまして。グエンです。', 'Rất vui được gặp. Tôi là Nguyễn.', 2),
