(63, 4, 'LISTENING', NULL, 'Nguyễn', 'どうも。どうぞ よろしく。', 'Cảm ơn anh. Mong được giúp đỡ.', 8),
(64, 5, 'LISTENING', NULL, 'Nguyễn', 'たなかさん、こちらは リンさんです。', 'Anh Tanaka, đây là chị Linh.', 1),
(65, 5, 'LISTENING', NULL, 'Linh', 'はじめまして。リンです。どうぞ よろしく。', 'Rất vui được gặp. Tôi là Linh. Mong được giúp đỡ.', 2),
(66, 5, 'LISTENING', NULL, 'Tanaka', 'リンさんも エンジニアですか。', 'Chị Linh cũng là kỹ sư phải không?', 3),
(67, 5, 'LISTENING', NULL, 'Linh', 'いいえ、ちがいます。がくせいです。', 'Không, không phải. Tôi là sinh viên.', 4),
