(72, 6, 'READING', NULL, 'Danh sách từ vựng bài 2', 'Bài 2 có 45 từ vựng.', NULL, 1),
(73, 8, 'GRAMMAR', 9, 'Ví dụ 1', 'これは ほん です。', 'Cái này là sách.', 1),
