(1446, 108, 'GRAMMAR', 117, 'Ví dụ 49', 'こどもが あそんで いる うみは にぎやか です。', 'Biển nơi trẻ con đang chơi thì nhộn nhịp.', 49),
(1447, 108, 'GRAMMAR', 120, 'Ví dụ 50', 'その ホテルは どんな ホテル ですか。', 'Khách sạn đó là khách sạn thế nào ạ?', 50),
(1448, 108, 'GRAMMAR', 117, 'Ví dụ 51', 'うたを うたって いる こどもは リンさん です。', 'Đứa trẻ đang hát bài hát là Linh.', 51),
(1449, 109, 'LISTENING', NULL, 'Nguyễn', 'あそこに いる ひとは だれですか。', 'Người đứng đằng kia là ai ạ?', 1),
(1450, 109, 'LISTENING', NULL, 'Tanaka', 'ドアの まえに たって いる ひとですか。', 'Người đang đứng trước cửa ấy à?', 2),
(1451, 109, 'LISTENING', NULL, 'Nguyễn', 'いいえ、まどの ちかくに すわって いる ひとです。', 'Không, người đang ngồi gần cửa sổ ạ.', 3),
(1452, 109, 'LISTENING', NULL, 'Tanaka', 'ああ、あの ひとは あたらしい どうりょうです。', 'À, người đó là đồng nghiệp mới.', 4),
(1453, 109, 'LISTENING', NULL, 'Nguyễn', 'うたって いる おんなのひとは。', 'Còn người phụ nữ đang hát ạ?', 5),
(1454, 109, 'LISTENING', NULL, 'Tanaka', 'リンさんですよ。うたが じょうずですね。', 'Là Linh đấy. Hát hay nhỉ.', 6),
(1455, 109, 'LISTENING', NULL, 'Nguyễn', 'ええ。よく きく うたです。', 'Vâng. Bài đó tôi hay nghe.', 7),
(1456, 109, 'LISTENING', NULL, 'Tanaka', 'じゃ、いっしょに いきましょう。', 'Vậy mình sang đó nhé.', 8),
(1457, 110, 'LISTENING', NULL, 'Linh', 'どんな へやが いいですか。', 'Phòng kiểu thế nào thì tốt ạ?', 1),
(1458, 110, 'LISTENING', NULL, 'Nguyễn', 'えきから ちかい へやが いいです。', 'Phòng gần ga thì tốt.', 2),
(1459, 110, 'LISTENING', NULL, 'Linh', 'しずかな ところも いいですね。', 'Nơi yên tĩnh cũng tốt anh nhỉ.', 3),
(1460, 110, 'LISTENING', NULL, 'Nguyễn', 'ええ。うみが みえる へやも いいですよ。', 'Ừ. Phòng nhìn ra biển cũng hay đấy.', 4),
(1461, 110, 'LISTENING', NULL, 'Linh', 'これは ともだちが おしえて くれた へやです。', 'Đây là căn bạn em chỉ cho.', 5),
(1462, 110, 'LISTENING', NULL, 'Nguyễn', 'こどもが あそんで いる こうえんの ちかくですね。', 'Gần cái công viên có bọn trẻ đang chơi nhỉ.', 6),
(1463, 110, 'LISTENING', NULL, 'Linh', 'はい。じかんが ある ひに みに いきます。', 'Vâng. Hôm nào rảnh em đi xem.', 7),
(1464, 110, 'LISTENING', NULL, 'Nguyễn', 'いっしょに いきましょうか。', 'Để anh đi cùng nhé?', 8),
(1465, 111, 'READING', NULL, 'Danh sách từ vựng bài 23', 'Bài 23 có 50 từ vựng.', NULL, 1),
(1466, 113, 'GRAMMAR', 121, 'Ví dụ 1', 'ひまな とき、ほんを よみます。', 'Lúc rảnh rỗi, tôi đọc sách.', 1),
(1467, 113, 'GRAMMAR', 121, 'Ví dụ 2', 'こどもの とき、よく さんぽしました。', 'Hồi còn bé, tôi thường đi dạo.', 2),
(1468, 113, 'GRAMMAR', 121, 'Ví dụ 3', 'いそがしい とき、やすみません。', 'Lúc bận rộn, tôi không nghỉ ngơi.', 3),
(1469, 113, 'GRAMMAR', 121, 'Ví dụ 4', 'さむい とき、ゆっくり ねます。', 'Lúc trời lạnh, tôi ngủ thong thả.', 4),
(1470, 113, 'GRAMMAR', 121, 'Ví dụ 5', 'でかける とき、きを つけます。', 'Lúc ra khỏi nhà, tôi chú ý cẩn thận.', 5),
(1471, 113, 'GRAMMAR', 122, 'Ví dụ 6', 'えきに ついた とき、でんわします。', 'Lúc đã tới ga, tôi sẽ gọi điện.', 6),
(1472, 113, 'GRAMMAR', 121, 'Ví dụ 7', 'やすむ とき、ほんを よみます。', 'Lúc nghỉ ngơi, tôi đọc sách.', 7),
(1473, 113, 'GRAMMAR', 121, 'Ví dụ 8', 'ひまな とき、さんぽします。', 'Lúc rảnh rỗi, tôi đi dạo.', 8),
(1474, 113, 'GRAMMAR', 121, 'Ví dụ 9', 'ひまな とき、おんがくを ききます。', 'Lúc rảnh rỗi, tôi nghe nhạc.', 9),
(1475, 113, 'GRAMMAR', 122, 'Ví dụ 10', 'ついた とき、でんわします。', 'Lúc đã tới nơi, tôi sẽ gọi điện.', 10),
(1476, 113, 'GRAMMAR', 123, 'Ví dụ 11', 'ボタンを おすと、でんきが つきます。', 'Hễ bấm nút thì đèn sáng.', 11),
