(1481, 113, 'GRAMMAR', 123, 'Ví dụ 16', 'まっすぐ いくと、えきが あります。', 'Hễ đi thẳng thì có nhà ga.', 16),
(1482, 113, 'GRAMMAR', 123, 'Ví dụ 17', 'ボタンを おすと、きっぷが でます。', 'Hễ bấm nút thì vé ra.', 17),
(1483, 113, 'GRAMMAR', 123, 'Ví dụ 18', 'つまみを まわすと、おんどが かわります。', 'Vặn núm là nhiệt độ đổi.', 18),
(1484, 113, 'GRAMMAR', 123, 'Ví dụ 19', 'きっぷを いれると、おとが でます。', 'Hễ bỏ vé vào thì máy kêu.', 19),
(1485, 113, 'GRAMMAR', 123, 'Ví dụ 20', 'ボタンを おすと、おとが でます。', 'Hễ bấm nút thì âm thanh phát ra.', 20),
(1486, 113, 'GRAMMAR', 123, 'Ví dụ 21', 'スイッチを まわすと、でんきが つきます。', 'Hễ vặn công tắc thì đèn sáng.', 21),
(1487, 113, 'GRAMMAR', 123, 'Ví dụ 22', 'スイッチを おすと、でんきが つきます。', 'Hễ bấm công tắc thì đèn sáng.', 22),
(1488, 113, 'GRAMMAR', 124, 'Ví dụ 23', 'スイッチを どうすると、でんきが つきますか。', 'Thao tác thế nào với công tắc thì đèn sáng?', 23),
(1489, 113, 'GRAMMAR', 121, 'Ví dụ 24', 'ねる とき、かぎを かけます。', 'Lúc đi ngủ, tôi khoá cửa.', 24),
(1490, 113, 'GRAMMAR', 121, 'Ví dụ 25', 'でかける とき、かぎを かけます。', 'Lúc ra khỏi nhà, tôi khoá cửa.', 25),
(1491, 113, 'GRAMMAR', 123, 'Ví dụ 26', 'きっぷを いれると、おとが でます。', 'Hễ bỏ vé vào thì âm thanh phát ra.', 26),
(1492, 113, 'GRAMMAR', 123, 'Ví dụ 27', 'ボタンを おすと、いろが かわります。', 'Hễ bấm nút thì màu sắc thay đổi.', 27),
(1493, 113, 'GRAMMAR', 124, 'Ví dụ 28', 'どうすると、いろが かわりますか。', 'Làm thế nào thì màu sắc thay đổi?', 28),
(1494, 113, 'GRAMMAR', 124, 'Ví dụ 29', 'どうすると、おんどが かわりますか。', 'Làm thế nào thì nhiệt độ thay đổi?', 29),
(1495, 113, 'GRAMMAR', 123, 'Ví dụ 30', 'きかいの つかいかたを みると、すぐ わかります。', 'Hễ xem cách dùng máy thì hiểu ngay.', 30),
(1496, 113, 'GRAMMAR', 124, 'Ví dụ 31', 'どうすると、でんきが つきますか。', 'Làm thế nào thì đèn sáng?', 31),
(1497, 113, 'GRAMMAR', 124, 'Ví dụ 32', 'いつ はなが さきますか。', 'Khi nào thì hoa nở?', 32),
(1498, 113, 'GRAMMAR', 121, 'Ví dụ 33', 'いそがしい とき、おんがくを ききます。', 'Lúc bận rộn, tôi nghe nhạc.', 33),
(1499, 113, 'GRAMMAR', 122, 'Ví dụ 34', 'がくせいの とき、よく ほんを よみました。', 'Hồi còn đi học, tôi đã đọc sách nhiều.', 34),
