(1768, 133, 'GRAMMAR', 139, 'Ví dụ 33', 'やっと じてんしゃに のれます。', 'Cuối cùng tôi cũng đi được xe đạp.', 33),
(1769, 133, 'GRAMMAR', 139, 'Ví dụ 34', 'スポーツが できます。', 'Tôi chơi được thể thao.', 34),
(1770, 133, 'GRAMMAR', 140, 'Ví dụ 35', 'テニスが できません。', 'Tôi không chơi được quần vợt.', 35),
