(1885, 143, 'GRAMMAR', 156, 'Ví dụ 15', 'かぎは かかって いますか。', 'Cửa đã khoá chưa?', 15),
(1886, 143, 'GRAMMAR', 156, 'Ví dụ 16', 'エアコンは ついて いますか。', 'Máy lạnh có đang bật không?', 16),
(1887, 143, 'GRAMMAR', 152, 'Ví dụ 17', 'まどを あけました。', 'Tôi đã mở cửa sổ.', 17),
(1888, 143, 'GRAMMAR', 152, 'Ví dụ 18', 'ドアを しめました。', 'Tôi đã đóng cửa ra vào.', 18),
(1889, 143, 'GRAMMAR', 152, 'Ví dụ 19', 'でんきを つけました。', 'Tôi đã bật đèn.', 19),
(1890, 143, 'GRAMMAR', 152, 'Ví dụ 20', 'でんきを けしました。', 'Tôi đã tắt đèn.', 20),
(1891, 143, 'GRAMMAR', 152, 'Ví dụ 21', 'かぎを かけました。', 'Tôi đã khóa cửa.', 21),
(1892, 143, 'GRAMMAR', 152, 'Ví dụ 22', 'エアコンを とめました。', 'Tôi đã tắt máy lạnh.', 22),
(1893, 143, 'GRAMMAR', 153, 'Ví dụ 23', 'さいふを なくして しまいました。', 'Tôi lỡ làm mất ví rồi.', 23),
(1894, 143, 'GRAMMAR', 153, 'Ví dụ 24', 'かさを わすれて しまいました。', 'Tôi lỡ quên ô mất rồi.', 24),
(1895, 143, 'GRAMMAR', 153, 'Ví dụ 25', 'けいたいを こわして しまいました。', 'Tôi lỡ làm hỏng điện thoại mất rồi.', 25),
(1896, 143, 'GRAMMAR', 153, 'Ví dụ 26', 'さいふを おとして しまいました。', 'Tôi lỡ đánh rơi ví mất rồi.', 26),
(1897, 143, 'GRAMMAR', 153, 'Ví dụ 27', 'さいふを よごして しまいました。', 'Tôi lỡ làm bẩn ví mất rồi.', 27),
(1898, 143, 'GRAMMAR', 153, 'Ví dụ 28', 'うっかり ねぼうして しまいました。', 'Lơ đãng tôi lỡ ngủ quên mất rồi.', 28),
(1899, 143, 'GRAMMAR', 154, 'Ví dụ 29', 'レポートは もう よんで しまいました。', 'Bản báo cáo thì tôi đã đọc xong rồi.', 29),
(1900, 143, 'GRAMMAR', 154, 'Ví dụ 30', 'しゅくだいは もう やって しまいました。', 'Bài tập tôi làm xong hết rồi.', 30),
(1901, 143, 'GRAMMAR', 154, 'Ví dụ 31', 'もう たべて しまいました。', 'Tôi đã ăn xong hết rồi.', 31),
(1902, 143, 'GRAMMAR', 154, 'Ví dụ 32', 'レポートは もう かいて しまいました。', 'Bản báo cáo thì tôi đã viết xong rồi.', 32),
(1903, 143, 'GRAMMAR', 156, 'Ví dụ 33', 'さいふは あいて いますか。', 'Ví có đang mở không?', 33),
(1904, 143, 'GRAMMAR', 156, 'Ví dụ 34', 'けいたいは ついて いますか。', 'Điện thoại có đang bật không?', 34),
(1905, 143, 'GRAMMAR', 153, 'Ví dụ 35', 'かさを なくして しまいました。', 'Tôi lỡ làm mất ô mất rồi.', 35),
(1906, 143, 'GRAMMAR', 151, 'Ví dụ 36', 'めがねが こわれて います。', 'Kính đang hỏng.', 36),
(1907, 143, 'GRAMMAR', 156, 'Ví dụ 37', 'しゅくだいは できて いますか。', 'Bài tập làm xong chưa?', 37),
(1908, 143, 'GRAMMAR', 155, 'Ví dụ 38', 'レポートは まだ かいて いません。', 'Bản báo cáo tôi vẫn chưa viết.', 38),
(1909, 143, 'GRAMMAR', 155, 'Ví dụ 39', 'そうじは まだ やって いません。', 'Việc dọn dẹp thì vẫn chưa làm.', 39),
(1910, 143, 'GRAMMAR', 155, 'Ví dụ 40', 'へんじは まだ かいて いません。', 'Hồi âm thì vẫn chưa viết.', 40),
(1911, 143, 'GRAMMAR', 155, 'Ví dụ 41', 'よやくは まだ して いません。', 'Việc đặt chỗ thì tôi chưa làm.', 41),
(1912, 143, 'GRAMMAR', 154, 'Ví dụ 42', 'へんじは もう かいて しまいました。', 'Hồi âm thì tôi đã viết xong rồi.', 42),
(1913, 143, 'GRAMMAR', 154, 'Ví dụ 43', 'しゅくだいは ぜんぶ やって しまいました。', 'Bài tập thì tôi đã làm xong toàn bộ rồi.', 43),
(1914, 143, 'GRAMMAR', 153, 'Ví dụ 44', 'うっかり さいふを なくして しまいました。', 'Lơ đãng tôi lỡ làm mất ví.', 44),
(1915, 143, 'GRAMMAR', 153, 'Ví dụ 45', 'さいふを なくして しまいましたから、しかたが ありません。', 'Lỡ mất ví rồi thì đành chịu thôi.', 45),
(1916, 143, 'GRAMMAR', 152, 'Ví dụ 46', 'だれかが ドアを あけました。', 'Ai đó đã mở cửa.', 46),
(1917, 143, 'GRAMMAR', 151, 'Ví dụ 47', 'いつのまにか でんきが ついて います。', 'Chẳng biết từ lúc nào đèn đã bật.', 47),
(1918, 143, 'GRAMMAR', 156, 'Ví dụ 48', 'ドアは どうして あいて いますか。', 'Sao cửa lại đang mở thế?', 48),
(1919, 143, 'GRAMMAR', 152, 'Ví dụ 49', 'こんどは わたしが ドアを あけました。', 'Lần này thì tôi là người mở cửa.', 49),
(1920, 143, 'GRAMMAR', 153, 'Ví dụ 50', 'ざんねんですが、さいふを なくして しまいました。', 'Tiếc thật, tôi lỡ làm mất ví rồi.', 50),
(1921, 144, 'LISTENING', NULL, 'Tanaka', 'グエンさん、まどは しまって いますか。', 'Anh Nguyễn, cửa sổ đóng chưa?', 1),
(1922, 144, 'LISTENING', NULL, 'Nguyễn', 'あ、まだ あいて います。しめます。', 'À, vẫn đang mở. Để tôi đóng.', 2),
(1923, 144, 'LISTENING', NULL, 'Tanaka', 'エアコンは きえて いますか。', 'Máy lạnh tắt chưa?', 3),
(1924, 144, 'LISTENING', NULL, 'Nguyễn', 'はい、さっき けしました。でんきも きえて います。', 'Rồi ạ, lúc nãy tôi tắt rồi. Đèn cũng tắt rồi.', 4),
(1925, 144, 'LISTENING', NULL, 'Tanaka', 'レポートは もう かきましたか。', 'Bản báo cáo viết xong chưa?', 5),
(1926, 144, 'LISTENING', NULL, 'Nguyễn', 'レポートは きのう かいて しまいました。', 'Bản báo cáo hôm qua tôi viết xong rồi.', 6),
(1927, 144, 'LISTENING', NULL, 'Tanaka', 'はやいですね。じゃ、かぎを かけましょう。', 'Nhanh thật đấy. Vậy ta khoá cửa thôi.', 7),
(1928, 144, 'LISTENING', NULL, 'Nguyễn', 'おねがいします。おつかれさまでした。', 'Nhờ anh ạ. Anh vất vả rồi.', 8),
(1929, 145, 'LISTENING', NULL, 'Tanaka', 'どうしたんですか。', 'Có chuyện gì thế?', 1),
(1930, 145, 'LISTENING', NULL, 'Linh', 'さいふを なくして しまいました。', 'Em lỡ làm mất ví rồi ạ.', 2),
(1931, 145, 'LISTENING', NULL, 'Tanaka', 'かばんの ひきだしは みましたか。', 'Em xem ngăn trong cặp chưa?', 3),
(1932, 145, 'LISTENING', NULL, 'Linh', 'みました。ひきだしは あいて いますが、なにも ありません。', 'Em xem rồi. Ngăn vẫn mở nhưng chẳng có gì cả.', 4),
(1933, 145, 'LISTENING', NULL, 'Tanaka', 'けいたいは ありましたか。', 'Điện thoại còn không?', 5),
(1934, 145, 'LISTENING', NULL, 'Linh', 'けいたいは あります。でんしゃで おとしたかもしれません。', 'Điện thoại thì còn ạ. Có lẽ em đánh rơi trên tàu.', 6),
(1935, 145, 'LISTENING', NULL, 'Tanaka', 'こうばんへ いきましょう。まだ ３じですから、あいて います。', 'Ta ra chốt cảnh sát đi. Mới ba giờ nên vẫn đang mở.', 7),
(1936, 145, 'LISTENING', NULL, 'Linh', 'ありがとう ございます。こんどは きを つけます。', 'Em cảm ơn anh. Lần tới em sẽ để ý.', 8),
(1937, 146, 'READING', NULL, 'Danh sách từ vựng bài 30', 'Bài 30 có 50 từ vựng.', NULL, 1),
(1938, 148, 'GRAMMAR', 161, 'Ví dụ 1', 'しりょうは じゅんびして ありますか。', 'Tài liệu đã chuẩn bị sẵn chưa?', 1),
(1939, 148, 'GRAMMAR', 157, 'Ví dụ 2', 'つくえに おちゃが おいて あります。', 'Có trà đã được đặt sẵn trên bàn làm việc.', 2),
(1940, 148, 'GRAMMAR', 157, 'Ví dụ 3', 'つくえの まえに いすが ならべて あります。', 'Ghế đã được xếp sẵn phía trước bàn làm việc.', 3),
(1941, 148, 'GRAMMAR', 157, 'Ví dụ 4', 'うけつけに めいぼが おいて あります。', 'Danh sách tên đã được đặt sẵn ở quầy tiếp đón.', 4),
(1942, 148, 'GRAMMAR', 157, 'Ví dụ 5', 'こくばんに よていが かいて あります。', 'Lịch đã ghi sẵn trên bảng.', 5),
(1943, 148, 'GRAMMAR', 157, 'Ví dụ 6', 'かいぎの しりょうが じゅんびして あります。', 'Tài liệu cuộc họp đã được chuẩn bị sẵn.', 6),
(1944, 148, 'GRAMMAR', 157, 'Ví dụ 7', 'つくえに いすが ならべて あります。', 'Ghế đã được kê sẵn bên bàn làm việc.', 7),
