(2055, 154, 'LISTENING', NULL, 'Tanaka', 'なつやすみは なにを する つもりですか。', 'Nghỉ hè anh định làm gì?', 1),
(2056, 154, 'LISTENING', NULL, 'Nguyễn', 'かぞくと りょこうする つもりです。', 'Tôi định đi chơi xa với gia đình.', 2),
(2057, 154, 'LISTENING', NULL, 'Tanaka', 'いいですね。どこへ いく つもりですか。', 'Hay quá nhỉ. Anh định đi đâu?', 3),
(2058, 154, 'LISTENING', NULL, 'Nguyễn', 'まだ きめて いません。うみが いいと おもいます。', 'Tôi vẫn chưa quyết. Tôi nghĩ đi biển thì hay.', 4),
(2059, 154, 'LISTENING', NULL, 'Tanaka', 'わたしは ８がつに しゅっちょうの よていです。', 'Tôi thì tháng tám có lịch đi công tác.', 5),
(2060, 154, 'LISTENING', NULL, 'Nguyễn', 'たいへんですね。かえりは いつの よていですか。', 'Vất vả nhỉ. Về thì theo lịch là khi nào ạ?', 6),
(2061, 154, 'LISTENING', NULL, 'Tanaka', 'つきまつの よていです。かえったら やすもうと おもいます。', 'Theo lịch là cuối tháng. Về xong tôi định nghỉ ngơi.', 7),
(2062, 154, 'LISTENING', NULL, 'Nguyễn', 'ゆっくり やすんで ください。', 'Anh nghỉ cho khoẻ nhé.', 8),
(2063, 155, 'LISTENING', NULL, 'Tanaka', 'そつぎょうは いつの よていですか。', 'Tốt nghiệp theo lịch là khi nào?', 1),
(2064, 155, 'LISTENING', NULL, 'Linh', 'らいねんの ３がつの よていです。', 'Theo lịch là tháng ba năm sau ạ.', 2),
(2065, 155, 'LISTENING', NULL, 'Tanaka', 'そのあとは どう する つもりですか。', 'Sau đó em định thế nào?', 3),
(2066, 155, 'LISTENING', NULL, 'Linh', 'にほんで はたらこうと おもいます。', 'Em định làm việc ở Nhật ạ.', 4),
(2067, 155, 'LISTENING', NULL, 'Tanaka', 'しけんは うける つもりですか。', 'Kỳ thi em định dự chứ?', 5),
(2068, 155, 'LISTENING', NULL, 'Linh', 'はい、１２がつに うけようと おもいます。', 'Vâng, tháng mười hai em định thi ạ.', 6),
(2069, 155, 'LISTENING', NULL, 'Tanaka', 'アルバイトは つづけますか。', 'Việc làm thêm em làm tiếp chứ?', 7),
(2070, 155, 'LISTENING', NULL, 'Linh', 'アルバイトは ふやさない つもりです。べんきょうが たいせつですから。', 'Việc làm thêm em định không nhận thêm. Vì học quan trọng hơn ạ.', 8),
