(2170, 163, 'GRAMMAR', 178, 'Ví dụ 32', 'この マークは ゆうりょうと いう いみです。', 'Ký hiệu này có nghĩa là mất phí.', 32),
(2171, 163, 'GRAMMAR', 177, 'Ví dụ 33', 'はりがみに ふりょうと かいて あります。', 'Trên tờ giấy dán ghi là hàng lỗi.', 33),
(2172, 163, 'GRAMMAR', 177, 'Ví dụ 34', 'はりがみに しめて くださいと かいて あります。', 'Trên tờ giấy dán ghi là xin hãy đóng.', 34),
(2173, 163, 'GRAMMAR', 177, 'Ví dụ 35', 'はりがみに おしてくださいと かいて あります。', 'Trên tờ giấy dán ghi là xin hãy đẩy.', 35),
(2174, 163, 'GRAMMAR', 177, 'Ví dụ 36', 'はりがみに ひいてくださいと かいて あります。', 'Trên tờ giấy dán ghi là xin hãy kéo.', 36),
(2175, 163, 'GRAMMAR', 179, 'Ví dụ 37', 'せんせいが はやく しろと いいました。', 'Thầy giáo đã nói là làm nhanh lên.', 37),
(2176, 163, 'GRAMMAR', 179, 'Ví dụ 38', 'コーチが いそげと いいました。', 'Huấn luyện viên đã nói là nhanh lên.', 38),
(2177, 163, 'GRAMMAR', 179, 'Ví dụ 39', 'ぶちょうが しずかに しろと いいました。', 'Trưởng phòng đã nói là im lặng đi.', 39),
(2178, 163, 'GRAMMAR', 179, 'Ví dụ 40', 'けいさつが とまれと いいました。', 'Cảnh sát đã nói là dừng lại.', 40),
(2179, 163, 'GRAMMAR', 176, 'Ví dụ 41', 'あぶないから はいるな。', 'Vì nguy hiểm nên đừng vào.', 41),
(2180, 163, 'GRAMMAR', 177, 'Ví dụ 42', 'かんばんに こうじちゅうと かいて あります。', 'Trên tấm biển ghi là đang thi công.', 42),
(2181, 163, 'GRAMMAR', 178, 'Ví dụ 43', 'この マークは きんしと いう いみです。', 'Ký hiệu này có nghĩa là cấm.', 43),
(2182, 163, 'GRAMMAR', 175, 'Ví dụ 44', 'いりぐちに ならべ。', 'Hãy xếp hàng ở lối vào.', 44),
(2183, 163, 'GRAMMAR', 180, 'Ví dụ 45', 'この ひょうしきは なんと かいて ありますか。', 'Biển hiệu này ghi cái gì vậy?', 45),
(2184, 163, 'GRAMMAR', 180, 'Ví dụ 46', 'こうじげんばの かんばんは どこに ありますか。', 'Tấm biển của công trường ở chỗ nào vậy?', 46),
(2185, 163, 'GRAMMAR', 180, 'Ví dụ 47', 'この かみは だれが かきましたか。', 'Tờ giấy này ai viết vậy?', 47),
(2186, 163, 'GRAMMAR', 177, 'Ví dụ 48', 'かみに みんなで つかってくださいと かいて あります。', 'Trên tờ giấy ghi là xin mọi người cùng dùng.', 48),
(2187, 163, 'GRAMMAR', 175, 'Ví dụ 49', 'つよい ことばで 「はやく しろ」と いいました。', 'Người ta nói bằng lời gắt: "nhanh lên".', 49),
(2188, 163, 'GRAMMAR', 178, 'Ví dụ 50', 'この ことばは ていねいに いうと いう いみです。', 'Từ này có nghĩa là nói một cách lịch sự.', 50),
(2189, 164, 'LISTENING', NULL, 'Nguyễn', 'たなかさん、この かんばんは なんと かいて ありますか。', 'Anh Tanaka, tấm biển này ghi gì thế ạ?', 1),
(2190, 164, 'LISTENING', NULL, 'Tanaka', 'たちいりきんしと かいて あります。', 'Ghi là cấm vào.', 2),
(2191, 164, 'LISTENING', NULL, 'Nguyễn', 'たちいりきんしは どういう いみですか。', 'Cấm vào nghĩa là gì ạ?', 3),
(2192, 164, 'LISTENING', NULL, 'Tanaka', 'はいるなと いう いみです。ここは こうじちゅうですから。', 'Nghĩa là đừng đi vào. Vì chỗ này đang thi công.', 4),
(2193, 164, 'LISTENING', NULL, 'Nguyễn', 'あの あかい かみは なんですか。', 'Tờ giấy đỏ kia là gì ạ?', 5),
(2194, 164, 'LISTENING', NULL, 'Tanaka', 'さわるなと かいて あります。きかいが あぶないんです。', 'Ghi là đừng chạm vào. Vì máy nguy hiểm.', 6),
(2195, 164, 'LISTENING', NULL, 'Nguyễn', 'わかりました。ヘルメットは いりますか。', 'Tôi hiểu rồi. Có cần mũ bảo hộ không ạ?', 7),
(2196, 164, 'LISTENING', NULL, 'Tanaka', 'はい。こうじげんばに ヘルメットちゃくようと かいて あります。', 'Có. Ở công trường ghi là phải đội mũ bảo hộ.', 8),
(2197, 165, 'LISTENING', NULL, 'Linh', 'あの ひょうしきは とまれと かいて ありますね。', 'Biển kia ghi là dừng lại nhỉ.', 1),
(2198, 165, 'LISTENING', NULL, 'Tanaka', 'そうです。とまれは つよい ことばです。', 'Đúng rồi. "Dừng lại" là lời nói gắt.', 2),
(2199, 165, 'LISTENING', NULL, 'Linh', 'ともだちにも つかえますか。', 'Với bạn bè có dùng được không ạ?', 3),
(2200, 165, 'LISTENING', NULL, 'Tanaka', 'つよい ことばだから、ともだちには つかうな。', 'Lời gắt đấy, đừng dùng với bạn bè.', 4),
(2201, 165, 'LISTENING', NULL, 'Linh', 'ていねいに いうと どう なりますか。', 'Nói cho lịch sự thì thành thế nào ạ?', 5),
(2202, 165, 'LISTENING', NULL, 'Tanaka', 'とまって くださいです。いみは おなじです。', 'Là "xin hãy dừng lại". Nghĩa thì như nhau.', 6),
(2203, 165, 'LISTENING', NULL, 'Linh', 'きんえんは どこに かいて ありますか。', 'Cấm hút thuốc ghi ở chỗ nào ạ?', 7),
(2204, 165, 'LISTENING', NULL, 'Tanaka', 'ホームに かいて あります。ここでは たばこを すうな。', 'Ghi ở sân ga. Ở đây thì đừng có hút thuốc.', 8),
(2205, 166, 'READING', NULL, 'Danh sách từ vựng bài 34', 'Bài 34 có 50 từ vựng.', NULL, 1),
(2206, 168, 'GRAMMAR', 182, 'Ví dụ 1', 'しょくじの あとで、くすりを のみます。', 'Sau bữa ăn thì uống thuốc.', 1),
(2207, 168, 'GRAMMAR', 182, 'Ví dụ 2', 'かいぎの あとで、でんわします。', 'Sau cuộc họp, tôi sẽ gọi điện.', 2),
(2208, 168, 'GRAMMAR', 186, 'Ví dụ 3', 'じゅぎょうの よしゅうは いつ しますか。', 'Việc chuẩn bị bài thì khi nào làm ạ?', 3),
(2209, 168, 'GRAMMAR', 182, 'Ví dụ 4', 'しごとの あとで、うんどうします。', 'Sau công việc, tôi tập thể dục.', 4),
