(2214, 168, 'GRAMMAR', 181, 'Ví dụ 9', 'せつめいの とおりに そうさします。', 'Thao tác đúng như lời hướng dẫn.', 9),
(2215, 168, 'GRAMMAR', 181, 'Ví dụ 10', 'レシピの とおりに つくります。', 'Tôi nấu đúng theo công thức.', 10),
(2216, 168, 'GRAMMAR', 181, 'Ví dụ 11', 'ならった とおりに します。', 'Tôi làm đúng như đã học.', 11),
(2217, 168, 'GRAMMAR', 181, 'Ví dụ 12', 'みた とおりに します。', 'Tôi làm đúng như đã thấy.', 12),
(2218, 168, 'GRAMMAR', 181, 'Ví dụ 13', 'やじるしの とおりに いきます。', 'Đi đúng theo hướng mũi tên.', 13),
(2219, 168, 'GRAMMAR', 183, 'Ví dụ 14', 'さとうを いれないで、つくります。', 'Không cho đường mà vẫn làm.', 14),
(2220, 168, 'GRAMMAR', 183, 'Ví dụ 15', 'かさを もたないで、いきます。', 'Không cầm ô mà vẫn đi.', 15),
(2221, 168, 'GRAMMAR', 183, 'Ví dụ 16', 'なにも たべないで、しごとを します。', 'Không ăn gì mà vẫn làm việc.', 16),
(2222, 168, 'GRAMMAR', 183, 'Ví dụ 17', 'じしょを つかわないで、よみます。', 'Không dùng từ điển mà vẫn đọc.', 17),
(2223, 168, 'GRAMMAR', 183, 'Ví dụ 18', 'ねないで、しごとを します。', 'Không ngủ mà vẫn làm việc.', 18),
(2224, 168, 'GRAMMAR', 184, 'Ví dụ 19', 'バスに のらないで、あるいて いきます。', 'Không đi xe buýt mà đi bộ đi.', 19),
(2225, 168, 'GRAMMAR', 184, 'Ví dụ 20', 'みせで かわないで、うちで つくります。', 'Không mua ở cửa hàng mà làm ở nhà.', 20),
(2226, 168, 'GRAMMAR', 184, 'Ví dụ 21', 'でんわしないで、いきます。', 'Không gọi điện mà đến trực tiếp.', 21),
(2227, 168, 'GRAMMAR', 185, 'Ví dụ 22', 'きかいには さわらないで ください。', 'Xin đừng chạm vào máy.', 22),
(2228, 168, 'GRAMMAR', 185, 'Ví dụ 23', 'しんぱいしないで ください。', 'Xin đừng lo lắng.', 23),
(2229, 168, 'GRAMMAR', 185, 'Ví dụ 24', 'むりを しないで ください。', 'Xin đừng gắng sức.', 24),
(2230, 168, 'GRAMMAR', 185, 'Ví dụ 25', 'くすりを のむのを わすれないで ください。', 'Xin đừng quên uống thuốc.', 25),
(2231, 168, 'GRAMMAR', 185, 'Ví dụ 26', 'じかんには おくれないで ください。', 'Xin đừng đến muộn giờ.', 26),
(2232, 168, 'GRAMMAR', 186, 'Ví dụ 27', 'レシピは どう しますか。', 'Công thức thì làm thế nào?', 27),
(2233, 168, 'GRAMMAR', 186, 'Ví dụ 28', 'さとうは どう しますか。', 'Đường thì làm thế nào?', 28),
(2234, 168, 'GRAMMAR', 181, 'Ví dụ 29', 'しおは レシピの とおりに いれます。', 'Muối thì cho vào đúng theo công thức.', 29),
(2235, 168, 'GRAMMAR', 182, 'Ví dụ 30', 'たまごを いれた あとで、みずを いれます。', 'Sau khi cho trứng vào, tôi cho nước vào.', 30),
(2236, 168, 'GRAMMAR', 182, 'Ví dụ 31', 'あぶらを いれた あとで、たまごを いれます。', 'Sau khi cho dầu ăn vào, tôi cho trứng vào.', 31),
(2237, 168, 'GRAMMAR', 183, 'Ví dụ 32', 'なべを つかわないで、つくります。', 'Không dùng nồi mà vẫn làm.', 32),
(2238, 168, 'GRAMMAR', 186, 'Ví dụ 33', 'そうさは どう しますか。', 'Thao tác thì làm thế nào ạ?', 33),
(2239, 168, 'GRAMMAR', 181, 'Ví dụ 34', 'せつめいの とおりに ボタンを おします。', 'Tôi bấm nút đúng như hướng dẫn.', 34),
(2240, 168, 'GRAMMAR', 186, 'Ví dụ 35', 'やじるしは どう しますか。', 'Mũi tên chỉ hướng thì làm thế nào?', 35),
(2241, 168, 'GRAMMAR', 182, 'Ví dụ 36', 'せつめいの あとで、ボタンを おします。', 'Sau lời hướng dẫn, tôi bấm nút.', 36),
(2242, 168, 'GRAMMAR', 181, 'Ví dụ 37', 'じゅんばんの とおりに します。', 'Làm đúng theo thứ tự.', 37),
(2243, 168, 'GRAMMAR', 183, 'Ví dụ 38', 'はんたいに しないで、じゅんばんの とおりに します。', 'Không làm ngược lại mà làm đúng theo thứ tự.', 38),
(2244, 168, 'GRAMMAR', 182, 'Ví dụ 39', 'その あとで、バスに のります。', 'Sau đó, tôi sẽ đi xe buýt.', 39),
(2245, 168, 'GRAMMAR', 182, 'Ví dụ 40', 'さきに てを あらいます。その あとで しょくじを します。', 'Tôi rửa tay trước. Sau đó mới ăn cơm.', 40),
(2246, 168, 'GRAMMAR', 181, 'Ví dụ 41', 'ゆっくり ならった とおりに します。', 'Từ tốn làm đúng như đã học.', 41),
(2247, 168, 'GRAMMAR', 185, 'Ví dụ 42', 'ちゃんと べんきょうして、まちがえないで ください。', 'Hãy học cho đàng hoàng, xin đừng làm sai.', 42),
(2248, 168, 'GRAMMAR', 185, 'Ví dụ 43', 'じゅんばんを まちがえないで ください。', 'Anh đừng làm sai thứ tự nhé.', 43),
(2249, 168, 'GRAMMAR', 182, 'Ví dụ 44', 'てを あらった あとで、しょくじを します。', 'Sau khi rửa tay, tôi ăn cơm.', 44),
(2250, 168, 'GRAMMAR', 182, 'Ví dụ 45', 'しょくじの あとで、かたづけます。', 'Sau bữa ăn, tôi dọn dẹp.', 45),
(2251, 168, 'GRAMMAR', 186, 'Ví dụ 46', 'そうじは いつ しますか。', 'Việc dọn dẹp thì làm khi nào?', 46),
(2252, 168, 'GRAMMAR', 186, 'Ví dụ 47', 'うんどうは この とおりに して ください。', 'Tập thể dục thì làm theo thế này nhé.', 47),
(2253, 168, 'GRAMMAR', 182, 'Ví dụ 48', 'くすりを のんだ あとで、やすみます。', 'Sau khi uống thuốc, tôi nghỉ ngơi.', 48),
(2254, 168, 'GRAMMAR', 183, 'Ví dụ 49', 'みずを のまないで、うんどうします。', 'Không uống nước mà vẫn vận động.', 49),
(2255, 168, 'GRAMMAR', 182, 'Ví dụ 50', 'しごとの あとで、そうじします。', 'Sau công việc, tôi dọn dẹp.', 50),
(2256, 169, 'LISTENING', NULL, 'Tanaka', 'まず、わたしが する とおりに して ください。', 'Trước hết anh làm y như tôi làm nhé.', 1),
(2257, 169, 'LISTENING', NULL, 'Nguyễn', 'はい。ボタンは いつ おしますか。', 'Vâng. Nút thì bấm lúc nào ạ?', 2),
(2258, 169, 'LISTENING', NULL, 'Tanaka', 'ボタンは かねが なった あとで おします。', 'Nút thì bấm sau khi có tiếng chuông.', 3),
(2259, 169, 'LISTENING', NULL, 'Nguyễn', 'わかりました。じゅんばんは どの とおりに しますか。', 'Tôi hiểu rồi. Thứ tự thì làm theo mẫu nào ạ?', 4),
(2260, 169, 'LISTENING', NULL, 'Tanaka', 'せつめいの とおりに そうさして ください。', 'Anh thao tác đúng như hướng dẫn nhé.', 5),
(2261, 169, 'LISTENING', NULL, 'Nguyễn', 'この あかい ところは さわりますか。', 'Chỗ đỏ này có chạm vào không ạ?', 6),
(2262, 169, 'LISTENING', NULL, 'Tanaka', 'いいえ、きかいには さわらないで ください。', 'Không, anh đừng chạm vào máy nhé.', 7),
(2263, 169, 'LISTENING', NULL, 'Nguyễn', 'はい。じゅんばんを まちがえないで やります。', 'Vâng. Tôi sẽ làm mà không sai thứ tự.', 8),
(2264, 170, 'LISTENING', NULL, 'Linh', 'レシピは どこに ありますか。', 'Công thức ở đâu ạ?', 1),
(2265, 170, 'LISTENING', NULL, 'Tanaka', 'けいたいに あります。レシピの とおりに つくれば だいじょうぶです。', 'Ở trong điện thoại. Nấu đúng như công thức là ổn.', 2),
(2266, 170, 'LISTENING', NULL, 'Linh', 'あぶらは いつ いれますか。', 'Dầu thì cho vào lúc nào ạ?', 3),
(2267, 170, 'LISTENING', NULL, 'Tanaka', 'あぶらは なべを あたためた あとで いれます。', 'Dầu thì cho sau khi làm nóng nồi.', 4),
(2268, 170, 'LISTENING', NULL, 'Linh', 'さとうは いれますか。', 'Có cho đường không ạ?', 5),
(2269, 170, 'LISTENING', NULL, 'Tanaka', 'この りょうりは さとうを いれないで つくります。', 'Món này nấu mà không cho đường.', 6),
(2270, 170, 'LISTENING', NULL, 'Linh', 'しおは どのぐらいですか。', 'Muối thì chừng bao nhiêu ạ?', 7),
(2271, 170, 'LISTENING', NULL, 'Tanaka', 'しおは レシピの とおりに いれて ください。', 'Muối thì em cho đúng như công thức nhé.', 8),
(2272, 171, 'READING', NULL, 'Danh sách từ vựng bài 35', 'Bài 35 có 50 từ vựng.', NULL, 1),
(2273, 173, 'GRAMMAR', 192, 'Ví dụ 1', 'とうきょうで ひっこしは どうすれば いいですか。', 'Chuyển nhà ở Tokyo thì làm thế nào thì tốt?', 1),
(2274, 173, 'GRAMMAR', 189, 'Ví dụ 2', 'きょうとなら はるが いいです。', 'Nếu là Kyoto thì mùa xuân là hợp nhất.', 2),
(2275, 173, 'GRAMMAR', 189, 'Ví dụ 3', 'おおさかなら みせが たくさん あります。', 'Nếu là Osaka thì có rất nhiều quán xá.', 3),
(2276, 173, 'GRAMMAR', 189, 'Ví dụ 4', 'ほっかいどうなら りょこうが いいです。', 'Nếu là Hokkaido thì đi du lịch rất tuyệt.', 4),
(2277, 173, 'GRAMMAR', 189, 'Ví dụ 5', 'おきなわなら りょこうが いいです。', 'Nếu là Okinawa thì đi chơi rất thích.', 5),
(2278, 173, 'GRAMMAR', 189, 'Ví dụ 6', 'とうきょうなら でんしゃが べんりです。', 'Nếu là Tokyo thì đi tàu điện rất tiện.', 6),
(2279, 173, 'GRAMMAR', 189, 'Ví dụ 7', 'ほっかいどうなら はるが いいです。', 'Nếu là Hokkaido thì mùa xuân rất tuyệt.', 7),
(2280, 173, 'GRAMMAR', 187, 'Ví dụ 8', 'はやく いけば きっぷが あります。', 'Hễ đi sớm thì sẽ còn vé.', 8),
(2281, 173, 'GRAMMAR', 187, 'Ví dụ 9', 'れんしゅうすれば うかります。', 'Hễ luyện tập thì sẽ đỗ.', 9),
