(2309, 173, 'GRAMMAR', 189, 'Ví dụ 37', 'りょこうなら たなかさんが いいです。', 'Nếu là đi du lịch thì nhờ anh Tanaka tư vấn là tốt nhất.', 37),
(2310, 173, 'GRAMMAR', 187, 'Ví dụ 38', 'べんきょうすれば うかります。', 'Hễ chăm học thì sẽ đỗ.', 38),
(2311, 173, 'GRAMMAR', 187, 'Ví dụ 39', 'はやく いけば まにあいます。', 'Hễ đi sớm thì sẽ kịp giờ.', 39),
(2312, 173, 'GRAMMAR', 187, 'Ví dụ 40', 'せんせいに きけば たすかります。', 'Hễ hỏi thầy cô thì đỡ quá.', 40),
(2313, 173, 'GRAMMAR', 188, 'Ví dụ 41', 'かわなければ こまります。', 'Nếu không mua thì gay đấy.', 41),
(2314, 173, 'GRAMMAR', 188, 'Ví dụ 42', 'はやく かわなければ うりきれます。', 'Nếu không mua nhanh thì bán hết sạch đấy.', 42),
(2315, 173, 'GRAMMAR', 191, 'Ví dụ 43', 'できれば いっしょに いきませんか。', 'Nếu được thì cùng đi với mình nhé?', 43),
(2316, 173, 'GRAMMAR', 191, 'Ví dụ 44', 'よければ いっしょに いきませんか。', 'Nếu tiện thì đi cùng mình nhé?', 44),
(2317, 173, 'GRAMMAR', 187, 'Ví dụ 45', 'そうすれば、もっと はやく なると おもいます。', 'Làm thế thì tôi nghĩ sẽ nhanh hơn.', 45),
(2318, 173, 'GRAMMAR', 192, 'Ví dụ 46', 'こうつうひは どうすれば やすく なりますか。', 'Tiền đi lại làm sao cho rẻ đi ạ?', 46),
(2319, 173, 'GRAMMAR', 192, 'Ví dụ 47', 'ふどうさんやは どこに ありますか。', 'Văn phòng nhà đất ở đâu ạ?', 47),
(2320, 173, 'GRAMMAR', 192, 'Ví dụ 48', 'ひっこしは いつなら やすいですか。', 'Chuyển nhà thì lúc nào rẻ ạ?', 48),
(2321, 173, 'GRAMMAR', 189, 'Ví dụ 49', 'かんじなら せんせいに きけば いいです。', 'Nếu nói tới chữ Hán thì hỏi thầy cô là được.', 49),
(2322, 173, 'GRAMMAR', 187, 'Ví dụ 50', 'がんばれば しけんに うかります。', 'Hễ cố gắng thì sẽ đỗ kỳ thi.', 50),
(2323, 174, 'LISTENING', NULL, 'Nguyễn', 'やちんは たかいですか。', 'Tiền nhà có đắt không ạ?', 1),
(2324, 174, 'LISTENING', NULL, 'Tanaka', 'やちんなら、この へやが いちばん やすいです。', 'Nếu nói tiền nhà thì phòng này rẻ nhất.', 2),
(2325, 174, 'LISTENING', NULL, 'Nguyễn', 'ひっこしは いつなら やすいですか。', 'Chuyển nhà thì lúc nào rẻ ạ?', 3),
(2326, 174, 'LISTENING', NULL, 'Tanaka', 'ひっこしなら、はるが やすいです。', 'Nếu là chuyển nhà thì mùa xuân rẻ.', 4),
(2327, 174, 'LISTENING', NULL, 'Nguyễn', 'こうつうひは どうすれば やすく なりますか。', 'Tiền đi lại làm sao cho rẻ đi ạ?', 5),
(2328, 174, 'LISTENING', NULL, 'Tanaka', 'じてんしゃに のれば、こうつうひが かかりません。', 'Hễ đi xe đạp thì không tốn tiền đi lại.', 6),
(2329, 174, 'LISTENING', NULL, 'Nguyễn', 'けいやくは はやい ほうが いいですか。', 'Hợp đồng thì nên làm sớm hơn ạ?', 7),
(2330, 174, 'LISTENING', NULL, 'Tanaka', 'はやければ はやいほど いいです。ふどうさんやで きけば、すぐ わかります。', 'Càng sớm càng tốt. Hễ hỏi ở văn phòng nhà đất là biết ngay.', 8),
(2331, 175, 'LISTENING', NULL, 'Linh', 'しけんは むずかしいですか。', 'Kỳ thi có khó không ạ?', 1),
(2332, 175, 'LISTENING', NULL, 'Tanaka', 'べんきょうしなければ、うかりません。でも がんばれば だいじょうぶです。', 'Nếu không học thì không đỗ. Nhưng hễ cố thì ổn thôi.', 2),
(2333, 175, 'LISTENING', NULL, 'Linh', 'かんじが おぼえられません。', 'Em không nhớ nổi chữ Hán.', 3),
(2334, 175, 'LISTENING', NULL, 'Tanaka', 'かんじは かかなければ、おぼえられません。てで かいて ください。', 'Chữ Hán nếu không viết thì không nhớ nổi. Em viết tay đi.', 4),
(2335, 175, 'LISTENING', NULL, 'Linh', 'はなすのも れんしゅうした ほうが いいですか。', 'Nói thì cũng nên luyện ạ?', 5),
(2336, 175, 'LISTENING', NULL, 'Tanaka', 'にほんごは はなせば はなすほど じょうずに なります。', 'Tiếng Nhật càng nói thì càng giỏi lên.', 6),
(2337, 175, 'LISTENING', NULL, 'Linh', 'わかりました。まいにち れんしゅうします。', 'Em hiểu rồi. Ngày nào em cũng luyện.', 7),
(2338, 175, 'LISTENING', NULL, 'Tanaka', 'よければ、わたしと はなしませんか。', 'Nếu tiện thì nói chuyện với tôi nhé?', 8),
(2339, 176, 'READING', NULL, 'Danh sách từ vựng bài 36', 'Bài 36 có 50 từ vựng.', NULL, 1),
(2340, 178, 'GRAMMAR', 193, 'Ví dụ 1', 'はやく はしれる ように、 まいにち うんどうして います。', 'Để có thể chạy nhanh, hằng ngày tôi đang vận động.', 1),
(2341, 178, 'GRAMMAR', 193, 'Ví dụ 2', 'かんじが よめる ように、 こえに だして よみます。', 'Để có thể đọc được chữ Hán, tôi sẽ đọc thành tiếng.', 2),
(2342, 178, 'GRAMMAR', 193, 'Ví dụ 3', 'しけんに うかる ように、 まいにち がんばって います。', 'Để đỗ kỳ thi, hằng ngày tôi đang cố gắng.', 3),
(2343, 178, 'GRAMMAR', 193, 'Ví dụ 4', 'かぜを ひかない ように、 みずを たくさん のみます。', 'Để không bị cảm, tôi sẽ uống nhiều nước.', 4),
(2344, 178, 'GRAMMAR', 193, 'Ví dụ 5', 'おくれない ように、 はやく おきるように して います。', 'Để không tới muộn, tôi đang cố giữ nếp dậy sớm.', 5),
(2345, 178, 'GRAMMAR', 195, 'Ví dụ 6', 'まいにち がんばって ふくしゅうするように して います。', 'Ngày nào tôi cũng chịu khó ôn lại bài.', 6),
(2346, 178, 'GRAMMAR', 195, 'Ví dụ 7', 'すこしずつ つづけて うんどうするように して います。', 'Tôi duy trì vận động đều, mỗi ngày một chút.', 7),
(2347, 178, 'GRAMMAR', 194, 'Ví dụ 8', 'にほんごが はなせるように なりました。', 'Tiếng Nhật giờ tôi nói được rồi.', 8),
(2348, 178, 'GRAMMAR', 194, 'Ví dụ 9', 'かんじが よめるように なりました。', 'Nay tôi đã đọc được chữ Hán rồi.', 9),
(2349, 178, 'GRAMMAR', 194, 'Ví dụ 10', 'やっと およげるように なりました。', 'Cuối cùng thì nay tôi đã bơi được rồi.', 10),
(2350, 178, 'GRAMMAR', 194, 'Ví dụ 11', 'けいたいが つかえるように なりました。', 'Nay tôi đã dùng được điện thoại rồi.', 11),
(2351, 178, 'GRAMMAR', 194, 'Ví dụ 12', 'はやく おきられるように なりました。', 'Nay tôi đã dậy sớm được rồi.', 12),
(2352, 178, 'GRAMMAR', 195, 'Ví dụ 13', 'ちかい ところは あるくように して います。', 'Chỗ nào gần thì tôi giữ nếp đi bộ.', 13),
(2353, 178, 'GRAMMAR', 195, 'Ví dụ 14', 'まいにち やさいを たべるように して います。', 'Tôi đang cố giữ nếp ăn rau mỗi ngày.', 14),
