(2594, 194, 'LISTENING', NULL, 'Nguyễn', 'はい。じこが あって、みちも とまりました。', 'Có ạ. Có tai nạn nên đường cũng tắc cứng.', 4),
(2595, 194, 'LISTENING', NULL, 'Tanaka', 'たいへんでしたね。パソコンは なおりましたか。', 'Vất vả rồi. Máy tính sửa được chưa?', 5),
(2596, 194, 'LISTENING', NULL, 'Nguyễn', 'パソコンは きのう なおりました。', 'Máy tính hôm qua sửa xong rồi.', 6),
(2597, 194, 'LISTENING', NULL, 'Tanaka', 'よかったです。あんしんしました。', 'May quá. Tôi yên tâm rồi.', 7),
(2598, 194, 'LISTENING', NULL, 'Nguyễn', 'ごめんなさい。あしたは はやめに でます。', 'Tôi xin lỗi. Mai tôi sẽ đi sớm hơn.', 8),
(2599, 195, 'LISTENING', NULL, 'Tanaka', 'しあいは どう なりましたか。', 'Trận đấu ra sao rồi?', 1),
(2600, 195, 'LISTENING', NULL, 'Linh', 'あめで しあいが ちゅうしに なりました。', 'Vì mưa mà trận đấu bị huỷ ạ.', 2),
(2601, 195, 'LISTENING', NULL, 'Tanaka', 'ざんねんでしたね。', 'Tiếc nhỉ.', 3),
(2602, 195, 'LISTENING', NULL, 'Linh', 'はい、ちゅうしに なって、ざんねんでした。', 'Vâng, bị huỷ nên em tiếc lắm.', 4),
(2603, 195, 'LISTENING', NULL, 'Tanaka', 'しらせは きましたか。', 'Tin báo tới chưa?', 5),
(2604, 195, 'LISTENING', NULL, 'Linh', 'しらせは けさ きました。ごうかくの しらせを きいて、うれしかったです。', 'Tin báo sáng nay tới rồi. Nghe tin đỗ em vui lắm.', 6),
(2605, 195, 'LISTENING', NULL, 'Tanaka', 'おめでとう ございます。がっこうは やすみですか。', 'Chúc mừng em. Trường có nghỉ không?', 7),
(2606, 195, 'LISTENING', NULL, 'Linh', 'たいふうで がっこうが やすみに なりました。', 'Vì bão mà trường thành nghỉ ạ.', 8),
(2607, 196, 'READING', NULL, 'Danh sách từ vựng bài 40', 'Bài 40 có 50 từ vựng.', NULL, 1),
(2608, 198, 'GRAMMAR', 217, 'Ví dụ 1', 'せきが あいて いるか どうか、わかりません。', 'Chỗ còn trống hay không thì tôi không rõ.', 1),
(2609, 198, 'GRAMMAR', 217, 'Ví dụ 2', 'かいぎに まにあうか どうか、わかりません。', 'Cuộc họp có kịp giờ hay không thì tôi không rõ.', 2),
(2610, 198, 'GRAMMAR', 217, 'Ví dụ 3', 'アプリが できるか どうか、わかりません。', 'Ứng dụng có làm được hay không thì tôi không rõ.', 3),
(2611, 198, 'GRAMMAR', 217, 'Ví dụ 4', 'サイズが ただしいか どうか、わかりません。', 'Kích cỡ có đúng hay không thì tôi không rõ.', 4),
(2612, 198, 'GRAMMAR', 217, 'Ví dụ 5', 'いんかんが ひつようか どうか、わかりません。', 'Con dấu có cần thiết hay không thì tôi không rõ.', 5),
(2613, 198, 'GRAMMAR', 220, 'Ví dụ 6', 'じむしょで かくにんします。', 'Tôi sẽ kiểm tra lại ở văn phòng.', 6),
(2614, 198, 'GRAMMAR', 220, 'Ví dụ 7', 'ちずで しらべます。', 'Tôi sẽ tra trên bản đồ.', 7),
(2615, 198, 'GRAMMAR', 219, 'Ví dụ 8', 'せんせいに きいて みます。', 'Tôi sẽ hỏi thử thầy giáo xem sao.', 8),
(2616, 198, 'GRAMMAR', 219, 'Ví dụ 9', 'ラーメンを たべて みます。', 'Tôi sẽ ăn thử món mì ramen xem sao.', 9),
(2617, 198, 'GRAMMAR', 219, 'Ví dụ 10', 'アプリを つかって みます。', 'Tôi sẽ dùng thử ứng dụng xem sao.', 10),
(2618, 198, 'GRAMMAR', 219, 'Ví dụ 11', 'じむしょに いって みます。', 'Tôi sẽ đến thử văn phòng xem sao.', 11),
(2619, 198, 'GRAMMAR', 219, 'Ví dụ 12', 'くつを はいて みます。', 'Tôi xỏ thử đôi giày.', 12),
(2620, 198, 'GRAMMAR', 219, 'Ví dụ 13', 'アプリを やって みます。', 'Tôi thử dùng ứng dụng xem sao.', 13),
(2621, 198, 'GRAMMAR', 218, 'Ví dụ 14', 'いくらか、しりません。', 'Giá bao nhiêu tiền thì tôi không biết.', 14),
(2622, 198, 'GRAMMAR', 218, 'Ví dụ 15', 'だれが くるか、わかりません。', 'Ai tới thì tôi không rõ.', 15),
(2623, 198, 'GRAMMAR', 218, 'Ví dụ 16', 'どこに おいたか、おぼえて いません。', 'Tôi để đâu thì tôi không nhớ.', 16),
(2624, 198, 'GRAMMAR', 218, 'Ví dụ 17', 'いつ はじまるか、きいて いません。', 'Bao giờ bắt đầu thì tôi chưa nghe nói.', 17),
(2625, 198, 'GRAMMAR', 221, 'Ví dụ 18', 'ばしょは しって います。', 'Về địa điểm thì tôi biết rồi.', 18),
(2626, 198, 'GRAMMAR', 221, 'Ví dụ 19', 'じゅぎょうの ばしょは わかりました。', 'Địa điểm buổi học thì tôi đã rõ rồi.', 19),
(2627, 198, 'GRAMMAR', 221, 'Ví dụ 20', 'よていは きまりました。', 'Về lịch trình thì đã chốt xong rồi.', 20),
(2628, 198, 'GRAMMAR', 220, 'Ví dụ 21', 'うけつけで かくにんします。', 'Tôi kiểm lại ở quầy tiếp đón.', 21),
(2629, 198, 'GRAMMAR', 220, 'Ví dụ 22', 'じむしょで しらべます。', 'Tôi sẽ tra thông tin ở văn phòng.', 22),
(2630, 198, 'GRAMMAR', 220, 'Ví dụ 23', 'ホームページで しらべます。', 'Tôi tra trên trang mạng.', 23),
(2631, 198, 'GRAMMAR', 220, 'Ví dụ 24', 'ちずで かくにんします。', 'Tôi sẽ kiểm tra lại trên bản đồ.', 24),
