(2634, 198, 'GRAMMAR', 222, 'Ví dụ 27', 'せきは あいて いますか。', 'Chỗ ngồi còn trống không ạ?', 27),
(2635, 198, 'GRAMMAR', 222, 'Ví dụ 28', 'ばしょは きまりましたか。', 'Địa điểm chốt chưa ạ?', 28),
(2636, 198, 'GRAMMAR', 222, 'Ví dụ 29', 'しけんの ひは きまりましたか。', 'Ngày thi đã được quyết định chưa?', 29),
(2637, 198, 'GRAMMAR', 222, 'Ví dụ 30', 'いんかんは ひつようですか。', 'Có cần con dấu tên không ạ?', 30),
(2638, 198, 'GRAMMAR', 222, 'Ví dụ 31', 'ラーメンは おいしいですか。', 'Mì ở đó có ngon không ạ?', 31),
(2639, 198, 'GRAMMAR', 219, 'Ví dụ 32', 'おいしい ラーメンを たべて みます。', 'Tôi sẽ ăn thử món mì ramen ngon xem sao.', 32),
(2640, 198, 'GRAMMAR', 219, 'Ví dụ 33', 'べんりな アプリを つかって みます。', 'Tôi sẽ dùng thử ứng dụng tiện lợi này xem sao.', 33),
(2641, 198, 'GRAMMAR', 219, 'Ví dụ 34', 'サイズが あうか はいて みます。', 'Tôi sẽ đi thử xem kích cỡ có vừa không.', 34),
(2642, 198, 'GRAMMAR', 218, 'Ví dụ 35', 'なんじから かいぎか、しりません。', 'Cuộc họp từ mấy giờ thì tôi không biết.', 35),
(2643, 198, 'GRAMMAR', 218, 'Ví dụ 36', 'だれが くるか、しりません。', 'Ai đến thì tôi không biết.', 36),
(2644, 198, 'GRAMMAR', 218, 'Ví dụ 37', 'どこで かいぎが あるか、しりません。', 'Cuộc họp ở đâu thì tôi không biết.', 37),
(2645, 198, 'GRAMMAR', 218, 'Ví dụ 38', 'ラーメンが いくらか、しりません。', 'Mì ramen bao nhiêu tiền thì tôi không biết.', 38),
(2646, 198, 'GRAMMAR', 222, 'Ví dụ 39', 'たんとうは だれですか。', 'Người phụ trách là ai ạ?', 39),
(2647, 198, 'GRAMMAR', 220, 'Ví dụ 40', 'よていを ホームページで しらべます。', 'Tôi sẽ tra lịch trình trên trang mạng.', 40),
(2648, 198, 'GRAMMAR', 222, 'Ví dụ 41', 'アプリは べんりですか。', 'Ứng dụng có tiện không ạ?', 41),
(2649, 198, 'GRAMMAR', 222, 'Ví dụ 42', 'サイズは あいますか。', 'Kích cỡ có vừa không?', 42),
(2650, 198, 'GRAMMAR', 219, 'Ví dụ 43', 'ちょっと たべて みます。', 'Tôi sẽ ăn thử một chút xem sao.', 43),
(2651, 198, 'GRAMMAR', 219, 'Ví dụ 44', 'いちど たべて みます。', 'Tôi sẽ ăn thử một lần xem sao.', 44),
(2652, 198, 'GRAMMAR', 220, 'Ví dụ 45', 'あとで アプリで しらべます。', 'Lát nữa tôi sẽ tra bằng ứng dụng.', 45),
(2653, 198, 'GRAMMAR', 217, 'Ví dụ 46', 'かいぎに まにあうか どうか、わかりません。', 'Có kịp cuộc họp hay không thì tôi không rõ.', 46),
(2654, 198, 'GRAMMAR', 217, 'Ví dụ 47', 'もし できなかったら、れんらくします。', 'Nếu không làm được thì tôi sẽ báo lại.', 47),
(2655, 198, 'GRAMMAR', 222, 'Ví dụ 48', 'じゅぎょうは いつ はじまりますか。', 'Buổi học bắt đầu khi nào ạ?', 48),
(2656, 198, 'GRAMMAR', 221, 'Ví dụ 49', 'じゅぎょうの ばしょは しって います。', 'Địa điểm buổi học thì tôi biết rồi.', 49),
(2657, 198, 'GRAMMAR', 217, 'Ví dụ 50', 'おいしいか どうか、たべて みます。', 'Tôi sẽ ăn thử xem có ngon hay không.', 50),
(2658, 199, 'LISTENING', NULL, 'Nguyễn', 'かいぎは なんじからですか。', 'Cuộc họp từ mấy giờ ạ?', 1),
(2659, 199, 'LISTENING', NULL, 'Tanaka', 'かいぎが なんじからか、しりません。じむしょに でんわして かくにんします。', 'Cuộc họp từ mấy giờ thì tôi không biết. Để tôi gọi văn phòng kiểm lại.', 2),
(2660, 199, 'LISTENING', NULL, 'Nguyễn', 'ばしょは きまりましたか。', 'Địa điểm chốt chưa ạ?', 3),
(2661, 199, 'LISTENING', NULL, 'Tanaka', 'ばしょは きまりました。３かいの へやです。', 'Địa điểm chốt rồi. Phòng tầng ba.', 4),
(2662, 199, 'LISTENING', NULL, 'Nguyễn', 'せきは あいて いますか。', 'Chỗ ngồi còn trống không ạ?', 5),
(2663, 199, 'LISTENING', NULL, 'Tanaka', 'せきが あいて いるか どうか、わかりません。うけつけで きいて みます。', 'Chỗ còn trống hay không thì tôi không rõ. Để tôi thử hỏi quầy tiếp đón.', 6),
(2664, 199, 'LISTENING', NULL, 'Nguyễn', 'たんとうは だれですか。', 'Người phụ trách là ai ạ?', 7),
(2665, 199, 'LISTENING', NULL, 'Tanaka', 'だれが たんとうか、しりません。あとで しらべます。', 'Ai phụ trách thì tôi không biết. Lát nữa tôi tra.', 8),
(2666, 200, 'LISTENING', NULL, 'Linh', 'ラーメンは おいしいですか。', 'Mì ở đây có ngon không ạ?', 1),
(2667, 200, 'LISTENING', NULL, 'Tanaka', 'ラーメンが おいしいか どうか、たべて みます。', 'Mì có ngon hay không, ăn thử là biết.', 2),
(2668, 200, 'LISTENING', NULL, 'Linh', 'ねだんは どうでしょうか。', 'Giá thì thế nào ạ?', 3),
(2669, 200, 'LISTENING', NULL, 'Tanaka', 'いくら かかるか、しりません。ホームページで しらべます。', 'Mất bao nhiêu thì tôi không biết. Để tôi tra trang mạng.', 4),
(2670, 200, 'LISTENING', NULL, 'Linh', 'アプリは べんりですか。', 'Ứng dụng có tiện không ạ?', 5),
(2671, 200, 'LISTENING', NULL, 'Tanaka', 'べんりか どうか、つかって みます。', 'Có tiện hay không, dùng thử xem.', 6),
(2672, 200, 'LISTENING', NULL, 'Linh', 'じゅぎょうは いつ はじまりますか。', 'Buổi học bắt đầu khi nào ạ?', 7),
(2673, 200, 'LISTENING', NULL, 'Tanaka', 'じゅぎょうは ９じからだと わかりました。まだ じかんが あります。', 'Buổi học từ chín giờ thì tôi rõ rồi. Vẫn còn thời gian.', 8),
