-- ---------------------------------------------------------------------------
-- kanji_reading: JOIN kanji.character -> id; idempotent theo (kanji_id, type, text)
-- ---------------------------------------------------------------------------
SELECT k.id, r.reading_type, r.reading_text, r.is_common
FROM (
  SELECT '一' AS ch, 'ON' AS reading_type, 'イチ' AS reading_text, 1 AS is_common
UNION ALL
